  "implementation": "import math

def solve(case):
    matrix = case["matrix"]
    N = len(matrix)
    if N == 0:
        return {"idf": [], "row_degree": [], "weighted_matrix": []}
    M = len(matrix[0])
    df = [0] * M
    for row in matrix:
        for j, val in enumerate(row):
            if val:
                df[j] += 1
    idf = [math.log(N / d) if d > 0 else 0.0 for d in df]
    row_degree = [sum(row) for row in matrix]
    weighted_matrix = [[matrix[i][j] * idf[j] for j in range(M)] for i in range(N)]
    return {"idf": idf, "row_degree": row_degree, "weighted_matrix": weighted_matrix}
